<section class="panel max-w-2xl text-center" role="status" aria-labelledby="maintenance-title">
    <span class="mx-auto inline-flex size-14 items-center justify-center rounded-full bg-[var(--accent-soft)] text-2xl text-[var(--accent)]" aria-hidden="true"><i class="ph ph-wrench"></i></span>
    <p class="dashboard-kicker mt-5">Scheduled maintenance</p>
    <h1 id="maintenance-title" class="mt-2 text-3xl font-extrabold tracking-tight sm:text-4xl">OEMS is temporarily unavailable.</h1>
